import{_ as a,o as i,c as n,ae as s}from"./chunks/framework.Czhw_PXq.js";const m=JSON.parse('{"title":"Capítulo 3: Arquitectura y Diseño Técnico","description":"","frontmatter":{},"headers":[],"relativePath":"tfm/03_arquitectura.md","filePath":"tfm/03_arquitectura.md"}'),o={name:"tfm/03_arquitectura.md"};function r(t,e,l,d,c,p){return i(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="capitulo-3-arquitectura-y-diseno-tecnico" tabindex="-1">Capítulo 3: Arquitectura y Diseño Técnico <a class="header-anchor" href="#capitulo-3-arquitectura-y-diseno-tecnico" aria-label="Permalink to &quot;Capítulo 3: Arquitectura y Diseño Técnico&quot;">​</a></h1><h2 id="_3-1-vision-general-de-la-arquitectura" tabindex="-1">3.1. Visión General de la Arquitectura <a class="header-anchor" href="#_3-1-vision-general-de-la-arquitectura" aria-label="Permalink to &quot;3.1. Visión General de la Arquitectura&quot;">​</a></h2><p>TenderCheck AI implementa una arquitectura desacoplada basada en servicios REST, siguiendo los principios de <strong>Clean Architecture</strong> (Arquitectura Limpia) postulados por Robert C. Martin. Este enfoque garantiza que la lógica de negocio (Dominio) permanezca independiente de frameworks, bases de datos o interfaces de usuario.</p><p><img src="https://mermaid.ink/img/pako:eNp1kU9rwjAQxb9KyGkL9a_gQWwvCiKIlx7soYfSjI2BNknIxFbE7960VVvowc0h7_1-82YmG6istWSCfF-oHdwqWcOjiQ9E8s-n84l4_v6wIJ8r_ECh02534C15h8oP1FdaW8V0-l3R6TzS1iit4B39VtrB9_3v_v-CD9RS6a00Dk5w7-AMHqBRGj1DqSfoHDr4hM6hE6fQWzgv9b3SG-hK3SlYqT-VfoN28AA9vH9DHzK5d_BdaQst4Q1-w0cIJYyghCnMYAZLWMESVvAAG1jDBvaQwh52sIcd-H4JJUyhgClMYAZLWMESVvAAG1jDBvaQwh52sIcd-H4JJUyhhClMYAZLWMESVvAAG1jDBvaQwh52sIcd-H4SSphCCVOYwAQWsIQVLMH__lZqD7N_38P8Bwuil6Y?type=png" alt="Diagrama Arquitectura"></p><h2 id="_3-2-estructura-del-proyecto-source-tree" tabindex="-1">3.2. Estructura del Proyecto (Source Tree) <a class="header-anchor" href="#_3-2-estructura-del-proyecto-source-tree" aria-label="Permalink to &quot;3.2. Estructura del Proyecto (Source Tree)&quot;">​</a></h2><p>La organización del código refleja la separación de responsabilidades:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TenderCheckAI/</span></span>
<span class="line"><span>├── backend/</span></span>
<span class="line"><span>│   ├── src/</span></span>
<span class="line"><span>│   │   ├── application/        # Casos de Uso (Orquestación)</span></span>
<span class="line"><span>│   │   │   ├── use-cases/      # Ej: CreateTender, ValidateProposal</span></span>
<span class="line"><span>│   │   │   ├── services/       # Ej: AuthService</span></span>
<span class="line"><span>│   │   ├── domain/             # Lógica de Negocio Pura (Nucleo)</span></span>
<span class="line"><span>│   │   │   ├── entities/       # Ej: Tender, Requirement, User</span></span>
<span class="line"><span>│   │   │   ├── interfaces/     # Contratos (ITenderAnalyzer, IUserRepository)</span></span>
<span class="line"><span>│   │   │   ├── services/       # Servicios de Dominio</span></span>
<span class="line"><span>│   │   │   └── validation/     # Reglas de Validación (Scope Check)</span></span>
<span class="line"><span>│   │   ├── infrastructure/     # Implementaciones Técnicas</span></span>
<span class="line"><span>│   │   │   ├── adapters/       # Ej: PdfParserAdapter</span></span>
<span class="line"><span>│   │   │   ├── services/       # Ej: OllamaModelService (IA Local)</span></span>
<span class="line"><span>│   │   │   ├── repositories/   # Ej: InMemoryUserRepository</span></span>
<span class="line"><span>│   │   │   └── server.ts       # Punto de entrada (Express)</span></span>
<span class="line"><span>│   │   └── presentation/       # API REST</span></span>
<span class="line"><span>│   │       ├── controllers/    # Ej: AuthController, TenderController</span></span>
<span class="line"><span>│   │       └── routes/         # Definición de Endpoints</span></span>
<span class="line"><span>│   └── test/</span></span>
<span class="line"><span>│       ├── unit/           # Tests unitarios (Vitest)</span></span>
<span class="line"><span>│       └── integration/    # Tests de integración (API)</span></span>
<span class="line"><span>├── frontend/</span></span>
<span class="line"><span>│   ├── src/</span></span>
<span class="line"><span>│   │   ├── components/         # Componentes React (UI)</span></span>
<span class="line"><span>│   │   │   ├── auth/           # Login/Register Forms</span></span>
<span class="line"><span>│   │   │   ├── dashboard/      # Panel Principal</span></span>
<span class="line"><span>│   │   │   └── ui/             # Elementos base (Botones, Inputs)</span></span>
<span class="line"><span>│   │   ├── services/           # Cliente API (Fetch)</span></span>
<span class="line"><span>│   │   ├── types.ts            # Definiciones de Tipos Compartidos</span></span>
<span class="line"><span>│   │   └── App.tsx             # Componente Raíz y Routing</span></span>
<span class="line"><span>└── docs/                       # Documentación del Proyecto</span></span>
<span class="line"><span>    ├── adr/                    # Decisiones de Arquitectura (ADRs)</span></span>
<span class="line"><span>    ├── standards/              # Normativa de Código</span></span>
<span class="line"><span>    └── tfm/                    # Memoria del Trabajo Fin de Máster</span></span></code></pre></div><h2 id="_3-3-descripcion-de-componentes-clave" tabindex="-1">3.3. Descripción de Componentes Clave <a class="header-anchor" href="#_3-3-descripcion-de-componentes-clave" aria-label="Permalink to &quot;3.3. Descripción de Componentes Clave&quot;">​</a></h2><h3 id="_3-3-1-capa-de-dominio-domain" tabindex="-1">3.3.1. Capa de Dominio (Domain) <a class="header-anchor" href="#_3-3-1-capa-de-dominio-domain" aria-label="Permalink to &quot;3.3.1. Capa de Dominio (Domain)&quot;">​</a></h3><p>Es el corazón del software. Define <em>qué</em> hace el sistema, no <em>cómo</em>.</p><ul><li><strong><code>TenderAnalysis</code></strong>: Entidad principal que agrega los requisitos extraídos.</li><li><strong><code>ITenderAnalyzer</code></strong>: Interfaz que abstrae el motor de IA. Esto nos permite cambiar de OpenAI a Ollama sin tocar el dominio.</li></ul><h3 id="_3-3-2-capa-de-aplicacion-application" tabindex="-1">3.3.2. Capa de Aplicación (Application) <a class="header-anchor" href="#_3-3-2-capa-de-aplicacion-application" aria-label="Permalink to &quot;3.3.2. Capa de Aplicación (Application)&quot;">​</a></h3><p>Actúa como <strong>orquestador</strong> del sistema. No contiene lógica de negocio compleja (que reside en el dominio) ni detalles técnicos (infraestructura), sino que coordina el flujo de datos.</p><ul><li><strong>Casos de Uso (Use Cases)</strong>: <ul><li><strong><code>CreateTender</code></strong>: Coordina la recepción del PDF, su parseo a texto y la llamada al servicio de IA para extraer requisitos.</li><li><strong><code>ValidateProposal</code></strong>: Ejecuta la lógica de comparación entre una oferta y los requisitos del pliego.</li></ul></li><li><strong>Servicios de Aplicación</strong>: <ul><li><strong><code>AuthService</code></strong>: Gestiona el flujo de registro y login, hasheando contraseñas y generando tokens, delegando la persistencia en el repositorio.</li><li><strong><code>ValidationRuleFactory</code></strong>: (Dominio/Aplicación) Permite la creación dinámica de reglas de validación (<code>IRule</code>) inyectando parámetros de configuración sectoriales desde la base de datos, siguiendo el patrón <em>Factory</em>.</li></ul></li></ul><h3 id="_3-3-3-capa-de-infraestructura-infrastructure" tabindex="-1">3.3.3. Capa de Infraestructura (Infrastructure) <a class="header-anchor" href="#_3-3-3-capa-de-infraestructura-infrastructure" aria-label="Permalink to &quot;3.3.3. Capa de Infraestructura (Infrastructure)&quot;">​</a></h3><p>Contiene los detalles técnicos y librerías externas.</p><ul><li><strong><code>MistralGenkitService</code></strong>: Implementación concreta que conecta con Mistral a través de Ollama (puerto 11434). Incluye lógica de <em>retry</em>, limpieza de JSON, y telemetría con Genkit.</li><li><strong>VectorSearchService</strong>: Servicio de búsqueda vectorial que genera embeddings con <code>gemini-embedding-001</code> (3072 dimensiones) y calcula similitud coseno para filtrado semántico de requisitos.</li><li><strong><code>SqliteTenderRepository</code></strong>: Implementación persistente utilizando SQLite. Gestiona el ciclo de vida de los análisis, requisitos, resultados de validación y <strong>embeddings vectoriales</strong> (almacenados como BLOB) mediante una base de datos relacional embebida.</li></ul><h3 id="_3-3-3-capa-de-presentacion-frontend" tabindex="-1">3.3.3. Capa de Presentación (Frontend) <a class="header-anchor" href="#_3-3-3-capa-de-presentacion-frontend" aria-label="Permalink to &quot;3.3.3. Capa de Presentación (Frontend)&quot;">​</a></h3><p>Desarrollada como una <strong>SPA</strong> (Single Page Application).</p><ul><li><strong>Gestión de Estado</strong>: React Hooks (<code>useState</code>, <code>useEffect</code>) para manejar la sesión del usuario y la carga de archivos.</li><li><strong>Componentes de Negocio</strong>: <ul><li><strong><code>HistorySidebar</code></strong>: Gestiona la visualización, búsqueda y eliminación de análisis previos persistidos.</li><li><strong><code>ValidationSummary</code></strong>: Motor gráfico que traduce los resultados crudos en estadísticas de cumplimiento (Mandatorios vs Opcionales).</li></ul></li><li><strong>Diseño</strong>: TailwindCSS para un diseño responsivo y modo oscuro nativo.</li></ul><h2 id="_3-4-decisiones-arquitectonicas-adrs" tabindex="-1">3.4. Decisiones Arquitectónicas (ADRs) <a class="header-anchor" href="#_3-4-decisiones-arquitectonicas-adrs" aria-label="Permalink to &quot;3.4. Decisiones Arquitectónicas (ADRs)&quot;">​</a></h2><p>Se han documentado formalmente las siguientes decisiones:</p><ul><li><strong>ADR-003</strong>: Inyección de Dependencias manual para mantener la simplicidad.</li><li><strong>ADR-005</strong>: Estrategia &quot;Local-First&quot; para IA y Autenticación, priorizando la privacidad de datos sensibles gubernamentales.</li><li><strong>ADR-022</strong>: Validación Dinámica basada en datos (Factoría de Reglas) para soportar múltiples industrias.</li></ul><h2 id="_3-5-subsistema-de-busqueda-vectorial-y-optimizacion" tabindex="-1">3.5. Subsistema de Búsqueda Vectorial y Optimización <a class="header-anchor" href="#_3-5-subsistema-de-busqueda-vectorial-y-optimizacion" aria-label="Permalink to &quot;3.5. Subsistema de Búsqueda Vectorial y Optimización&quot;">​</a></h2><p>Para mejorar el rendimiento y preparar el sistema para filtrado semántico, se ha implementado una infraestructura de búsqueda vectorial:</p><ol><li><strong>Generación de Embeddings</strong>: Durante la creación del tender, cada requisito se convierte en un vector de 3072 dimensiones usando <code>gemini-embedding-001</code>.</li><li><strong>Almacenamiento</strong>: Los embeddings se guardan en SQLite como columnas BLOB, permitiendo persistencia sin dependencias externas.</li><li><strong>Similitud Coseno</strong>: Implementación de cálculo de similitud para futuras optimizaciones de filtrado.</li><li><strong>Procesamiento Paralelo</strong>: Validación de 3 requisitos simultáneamente (3x concurrencia) para reducir el tiempo de validación de 5+ minutos a 2-3 minutos.</li><li><strong>Determinismo</strong>: Temperatura 0.0 en Mistral para garantizar resultados consistentes (89% de precisión).</li></ol><h2 id="_3-6-estrategia-de-diseno-de-interfaz-ui-ux" tabindex="-1">3.6. Estrategia de Diseño de Interfaz (UI/UX) <a class="header-anchor" href="#_3-6-estrategia-de-diseno-de-interfaz-ui-ux" aria-label="Permalink to &quot;3.6. Estrategia de Diseño de Interfaz (UI/UX)&quot;">​</a></h2><p>El diseño del frontend se rige por principios de usabilidad centrados en el usuario administrativo.</p><h3 id="_3-6-1-heuristicas-de-nielsen" tabindex="-1">3.6.1. Heurísticas de Nielsen <a class="header-anchor" href="#_3-6-1-heuristicas-de-nielsen" aria-label="Permalink to &quot;3.6.1. Heurísticas de Nielsen&quot;">​</a></h3><ul><li><strong>Visibilidad del Estado</strong>: Uso de indicadores de carga (Spinners) y mensajes de éxito/error claros (Toasts).</li><li><strong>Consistencia</strong>: Unificación de identidad visual &quot;Emerald &amp; Gold&quot;. <code>Landing Page</code> (Light Sage) vs <code>Dashboard</code> (Soft Charcoal).</li><li><strong>Design System</strong>: TailwindCSS con tokens semánticos (<code>brand-dark</code>, <code>brand-gold</code>).</li><li><strong>Prevención de Errores</strong>: Validación de formularios en tiempo real con <code>Zod</code> y <code>React Hook Form</code> antes del envío.</li></ul><h3 id="_3-6-2-accesibilidad-a11y" tabindex="-1">3.6.2. Accesibilidad (A11y) <a class="header-anchor" href="#_3-6-2-accesibilidad-a11y" aria-label="Permalink to &quot;3.6.2. Accesibilidad (A11y)&quot;">​</a></h3><p>Se cumple con el nivel AA de las WCAG 2.1:</p><ul><li>Contraste de colores suficiente (verificado en Modo Oscuro).</li><li>Elementos interactivos con etiquetas <code>aria-label</code>.</li><li>Navegabilidad completa mediante teclado.</li></ul><h2 id="_3-7-estrategia-de-calidad-y-pruebas" tabindex="-1">3.7. Estrategia de Calidad y Pruebas <a class="header-anchor" href="#_3-7-estrategia-de-calidad-y-pruebas" aria-label="Permalink to &quot;3.7. Estrategia de Calidad y Pruebas&quot;">​</a></h2><p>La arquitectura soporta una estrategia de testing piramidal:</p><ul><li><strong>Unit Testing (Vitest)</strong>: Cobertura objetiva &gt;71% en lógica de negocio (Core Branch) y &gt;60% global.</li><li><strong>Integration Testing</strong>: Verificación de los adaptadores (Ollama service, Repositorios) con datos mockeados.</li><li><strong>Static Analysis</strong>: ESLint y TypeScript en modo estricto para prevenir errores en tiempo de compilación.</li></ul><h2 id="_3-8-capa-de-seguridad-defense-in-depth" tabindex="-1">3.8. Capa de Seguridad (Defense in Depth) <a class="header-anchor" href="#_3-8-capa-de-seguridad-defense-in-depth" aria-label="Permalink to &quot;3.8. Capa de Seguridad (Defense in Depth)&quot;">​</a></h2><p>Se han implementado salvaguardas en múltiples niveles:</p><ol><li><strong>Rate Limiting</strong>: Protección contra fuerza bruta en login (3 intentos/15 min).</li><li><strong>Validación Robusta</strong>: Doble verificación en subida de PDFs (Multer + Zod) y complejidad estricta de contraseñas.</li><li><strong>Observabilidad</strong>: Integración de <strong>Sentry</strong> para trazas de error y <strong>Snyk</strong> para escaneo de vulnerabilidades.</li></ol><h2 id="_3-9-principios-de-diseno-de-software-solid" tabindex="-1">3.9. Principios de Diseño de Software (SOLID) <a class="header-anchor" href="#_3-9-principios-de-diseno-de-software-solid" aria-label="Permalink to &quot;3.9. Principios de Diseño de Software (SOLID)&quot;">​</a></h2><p>El desarrollo del backend se ha adherido estrictamente a los principios SOLID para asegurar mantenibilidad:</p><ol><li><strong>S - Single Responsibility Principle (SRP)</strong>: <ul><li>Cada clase tiene una única razón para cambiar. Ejemplo: <code>OllamaModelService</code> solo se encarga de hablar con la IA, no de guardar datos en la DB.</li></ul></li><li><strong>O - Open/Closed Principle (OCP)</strong>: <ul><li>Las entidades están abiertas a extensión pero cerradas a modificación. Ejemplo: Podemos añadir nuevos validadores de reglas sin modificar el <code>ValidationEngine</code> principal.</li></ul></li><li><strong>L - Liskov Substitution Principle (LSP)</strong>: <ul><li>Las implementaciones de repositorios (<code>InMemoryUserRepository</code>) son intercambiables por futuras implementaciones SQL sin romper la aplicación.</li></ul></li><li><strong>I - Interface Segregation Principle (ISP)</strong>: <ul><li>Las interfaces como <code>ITenderAnalyzer</code> son pequeñas y específicas, evitando obligar a las clases a implementar métodos que no usan.</li></ul></li><li><strong>D - Dependency Inversion Principle (DIP)</strong>: <ul><li>Los Casos de Uso dependen de abstracciones (<code>ITenderAnalyzer</code>), no de detalles concretos (<code>OpenAI</code> o <code>Ollama</code>). Esto permitió migrar de OpenAI a Ollama cambiando una sola línea en <code>TenderRoutes.ts</code>.</li></ul></li></ol>`,42)])])}const g=a(o,[["render",r]]);export{m as __pageData,g as default};
